package com.skyrpg.core.client.theme;

import com.skyrpg.core.SkyRpgCore;
import com.skyrpg.core.client.config.SkyRpgSettings;
import java.util.List;
import net.fabricmc.fabric.api.resource.v1.ResourceLoader;
import net.fabricmc.fabric.api.resource.v1.reloader.SimpleReloadListener;
import net.minecraft.client.Minecraft;
import net.minecraft.resources.Identifier;
import net.minecraft.server.packs.PackType;
import net.minecraft.server.packs.repository.PackRepository;

/**
 * The SkyRPG theme for vanilla screens: a built-in resource pack (generated by
 * {@code tools/theme/generate_theme.py} into {@code resourcepacks/skyrpg_theme}) that re-skins
 * Minecraft's widgets and containers, switched on and off from Settings.
 *
 * <p>Switching it on and off is shared with the other built-in packs, see {@link ToggledPacks}.
 */
public final class ThemePack {
    public static final Identifier ID = SkyRpgCore.id("skyrpg_theme");
    /** How the pack appears in the pack repository and options.txt. */
    public static final String PACK_ID = ID.toString();

    /** Vanilla draws container titles ("Inventory", "Chest") in this dark grey; unreadable on dark panels. */
    private static final int VANILLA_LABEL = 0xFF404040;
    private static final int THEMED_LABEL = 0xFFC9D0DC;

    private static boolean active;

    private ThemePack() {
    }

    /** Called once from the core client entrypoint, after the settings are loaded. */
    public static void register() {
        ToggledPacks.register(ID, "SkyRPG Theme", "interface.theme", SkyRpgSettings.INTERFACE,
                "SkyRPG theme for all screens", "Restyle Minecraft's own menus, buttons and inventories to match SkyRPG", true);
        // Track the real state after every resource reload, including changes made in the vanilla pack screen.
        ResourceLoader.get(PackType.CLIENT_RESOURCES).registerReloadListener(SkyRpgCore.id("theme_state"), new SimpleReloadListener<Void>() {
            @Override
            protected Void prepare(SharedState state) {
                return null;
            }

            @Override
            protected void apply(Void unused, SharedState state) {
                active = Minecraft.getInstance().getResourcePackRepository().getSelectedIds().contains(PACK_ID);
            }
        });
    }

    /** Whether the theme's textures are in use right now. */
    public static boolean isActive() {
        return active;
    }

    /** Swaps vanilla's dark label grey for a light one while the theme is on. */
    public static int labelColor(int color) {
        return active && color == VANILLA_LABEL ? THEMED_LABEL : color;
    }

    /** Kept for {@code OptionsMixin}: syncs every toggled pack (theme, classic icons) with its setting. */
    public static void beforePacksLoaded(List<String> selected, PackRepository repository) {
        ToggledPacks.beforePacksLoaded(selected, repository);
    }
}
